@startuml

class SensorController {
}

class Apartment {
  +address : string
  +emailAddress : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Administrator extends Inhabitant {
}

class Room {
  +description : string
}

abstract class Sensor {
  +vendorId : string
  +description : string
  +unit : Unit
}

class TemperatureSensor extends Sensor {
  +min : float
  +max : float
}

class PowerSensor extends Sensor {
  +counterReading : float
}

class MeasuredValue {
  +timestamp : datetime
  +value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
}

SensorController "1" -- "*" Apartment : manages
SensorController "1" -- "*" Inhabitant : manages
Apartment "1" -- "1..*" Room : consists of
Room "1" -- "1" Sensor : contains
Sensor "1" -- "*" MeasuredValue : records
Sensor "1" -- "0..1" MeasuredValue : lastValue
Sensor "*" -- "0..1" Administrator : configured by
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "1" SensorController : uses

@enduml

